                       live outer. */
  pComponent = StaticConstructObject_Internal(pClass,pDefaultOuter,0,0,0,(void *)0x0,0,(void *)0x0);
  pComponent->dwAutoActivateFlags = pComponent->dwAutoActivateFlags & 0xfffffffe;
