                       registers or activates the component. */
  SetParticleSystemComponentTemplateAndResetState(pComponent,pParticleTemplate);
  pComponent->dwPostCreateFlags = pComponent->dwPostCreateFlags & 0xfffffffe;
  return pComponent;
}

